def proverb(*rhyme_items, qualifier):
    if not rhyme_items:
        return []
    phrases = [
        f'For want of a {first} the {second} was lost.'
        for first, second in zip(rhyme_items, rhyme_items[1:])
    ]
    first_item = rhyme_items[0]
    if qualifier:
        first_item = f'{qualifier} {first_item}'
    phrases.append(f'And all for the want of a {first_item}.')
    return phrases

