def rectangles(strings=''):
    total = 0
    for top, top_row in enumerate(strings):
        vertical = [char == '+' for char in top_row]
        for bottom in range(top + 1, len(strings)):
            previous_corners = 0
            for col, char in enumerate(strings[bottom]):
                vertical[col] = vertical[col] and char in '|+'
                if char not in '-+' or top_row[col] not in '-+':
                    previous_corners = 0
                elif vertical[col] and char == '+':
                    total += previous_corners
                    previous_corners += 1
    return total

